import{_ as a,a as t,o as p,y as o}from"./chunks/framework.kB5lbtep.js";const _="/media/novels/nambu_blue/zygote_of_civi.png",n="/media/novels/nambu_blue/old_gate.png",b=JSON.parse('{"title":"一、文化密码","description":"","frontmatter":{},"headers":[],"relativePath":"novels/nambu_blue/1.1.md","filePath":"novels/nambu_blue/1.1.md"}'),r={name:"novels/nambu_blue/1.1.md"};function s(l,e,i,m,c,d){return p(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="一、文化密码" tabindex="-1">一、文化密码 <a class="header-anchor" href="#一、文化密码" aria-label="Permalink to &quot;一、文化密码&quot;">​</a></h1><h2 id="_1-南武-是广州城最早的称呼" tabindex="-1">1. 南武，是广州城最早的称呼 <a class="header-anchor" href="#_1-南武-是广州城最早的称呼" aria-label="Permalink to &quot;1. 南武，是广州城最早的称呼&quot;">​</a></h2><p>“南武”不是南方武术学校的简称。“南武”是广州城最早的称呼！</p><p>为什么用“南武”命名？南武公学会同人、南武先贤朱信校友在1985年校庆前夕写的一篇短文是这样记载的：用“南武”命名取义有三：南武是周代的文章典制，代表古代文明；南武是广东省城最古的名字，是广东人亲手建立的名城；“南武”二字最能代表粤人英爽、文明、勤劳、勇敢、坚忍等优良性格。</p><p>所以，用“南武”命名，表达的是“教典不忘始祖”“昭兹来许，绳其祖武”的南武教育初心。</p><p>如今，南武校园沧海桑田，但校址依旧，弦歌不辍，古木荫翳，意境别致，颇多情趣；一草一木，一景一物，渗透着古朴典雅之风尚，浸润着蓝色文明之韵律，蕴含着“坚忍奉公，力学爱国”的精神，散发着“古风·蓝韵’拓潜”的文化魅力。</p><p>百年南武，教育依然“稳重如山，灵动似水”。一所学校，一个人、只有把自已的名字根植于厚重的历史沃土、优秀的文化良田之上时，只有把自己的命运与国家、民族的命运联系在一起时，才真正配得上“君子自强不息、厚德载物”的古训，其境界、其品格，就自显高尚！</p><p>2010年3月，九十三岁的“国医大师”邓铁涛教授为南武题词“止戈为武”。邓老以此题词诠释对南武的情愫，寄托对南武教育发展的哲理思考。据查，此语出自《左传·宣公十二年》，是楚庄王的一个著名论点，意即“武”字是由“止”和“戈”两字合成的，真正的武功是永远停动用武器。邓老引古训师后人，诠释南武人的智慧，为南武创新发展再添智慧、哲理的注脚！</p><p>“南武当作诗句读，名校要如古琴听。”南武自有南武的蕴藉，名校自有名校的弦歌。和先贤同校，与名师为友，百年文化沉淀，世纪儒雅浸润，就读南武，筑梦南武，心之所向，素履以往！</p><p>漫步在南武校园，看古迹美景，听故事趣闻，讲百年风云，赏中西景致，如沐浴人文之春风，氤氲文化之气息，感慨百年南武的教育如诗之风韵，山之沉稳，水之灵动。</p><p><img src="'+_+'" alt="1-1"></p><p>图1-1：著名书画家、南武中学荣誉校长陈永锵为南武中学题词</p><p><img src="'+n+'" alt="1-2"></p><p>图1-2：旧时南武学校大门</p>',14)])])}const h=a(r,[["render",s]]);export{b as __pageData,h as default};
